$showFormDialog(
    {
      'title': 'Add Setup Material',
      'formInputs': [
        {
          "name": "Quantity",
          "description": "",
          "label": "Enter Quantity of Material being loaded",
          "type": "number",
          "dataPath": "quantity",
          "validation": {
            "required": true
          },
          "defaultValue": "1"          
        },
        {
          "name": "Serial Number",
          "description": "",
          "label": "Enter Serial Number of Material being loaded",
          "type": "text",
          "dataPath": "serial",
          "validation": {
            "required": true
          }
        }
      ], 
      'submitIcon': 'plus',
      'data': {
        'description': '',
        'versionNumber': '0.0.1'
      }
    }
  )

($card.data.wip and serial) or $not($card.data.wip) and quantity ? $executeFlow("controlPanelWebFlow",{
  "ACTION": "LOAD_SETUP_MATERIAL",
  "REQUEST":{
    "DATA": {
      "productId": $card.data.componentProduct.id,
      "productCode": $card.data.componentProduct.code,
      "quantity": $number(quantity),
      "serial": serial,
      "wip": $card.data.wip,
      "workunitId": $metadata.urlParameters.id
    }
  }
})
